<?php
require_once __DIR__ . '/config.php';
$err = ''; $ok = '';
$installed = false;
try { $t = new PDO('mysql:host=' . DB_HOST . ';charset=utf8mb4', DB_USER, DB_PASS); $t->query("SELECT 1 FROM `" . DB_NAME . "`.users LIMIT 1"); $installed = true; } catch (Exception $e) {}

if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['install'])) {
    try {
        $pdo = new PDO('mysql:host=' . DB_HOST . ';charset=utf8mb4', DB_USER, DB_PASS, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
        $pdo->exec("CREATE DATABASE IF NOT EXISTS `" . DB_NAME . "` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");
        $pdo->exec("USE `" . DB_NAME . "`");
        $pdo->exec("CREATE TABLE IF NOT EXISTS `users` (`id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`username` VARCHAR(50) UNIQUE NOT NULL,`password` VARCHAR(255) NOT NULL,`email` VARCHAR(100) DEFAULT NULL,`display_name` VARCHAR(100) DEFAULT NULL,`role` ENUM('admin','editor','author') DEFAULT 'author',`created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        $pdo->exec("CREATE TABLE IF NOT EXISTS `categories` (`id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`name` VARCHAR(100) NOT NULL,`slug` VARCHAR(100) UNIQUE NOT NULL,`description` TEXT DEFAULT NULL,`color` VARCHAR(20) DEFAULT '#3b6ef5',`sort_order` INT DEFAULT 0,`created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        $pdo->exec("CREATE TABLE IF NOT EXISTS `posts` (`id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`title` VARCHAR(255) NOT NULL,`slug` VARCHAR(255) UNIQUE NOT NULL,`content` LONGTEXT DEFAULT NULL,`excerpt` TEXT DEFAULT NULL,`cover_image` VARCHAR(500) DEFAULT NULL,`category_id` INT UNSIGNED DEFAULT NULL,`type` ENUM('post','sharing') DEFAULT 'post',`status` ENUM('draft','published') DEFAULT 'draft',`is_featured` TINYINT(1) DEFAULT 0,`view_count` INT UNSIGNED DEFAULT 0,`created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,`updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,`published_at` DATETIME DEFAULT NULL,INDEX `idx_st`(`status`,`type`),FOREIGN KEY(`category_id`) REFERENCES `categories`(`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        $pdo->exec("CREATE TABLE IF NOT EXISTS `settings` (`id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`setting_key` VARCHAR(100) UNIQUE NOT NULL,`setting_value` TEXT DEFAULT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        $pdo->exec("CREATE TABLE IF NOT EXISTS `wishes` (`id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`nickname` VARCHAR(50) NOT NULL,`content` TEXT NOT NULL,`wish_type` ENUM('message','wish') DEFAULT 'message',`avatar_color` VARCHAR(20) DEFAULT '#3b6ef5',`status` ENUM('visible','hidden') DEFAULT 'visible',`created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

        $hash = password_hash($_POST['admin_pass'] ?: 'moyu123', PASSWORD_DEFAULT);
        $pdo->prepare("INSERT IGNORE INTO users (username,password,email,display_name,role) VALUES (?,?,?,?,?)")
            ->execute([$_POST['admin_user'] ?: 'admin', $hash, $_POST['admin_email'] ?: 'admin@moyublog.local', '摸鱼管理员', 'admin']);

        $cats = [['技术折腾','tech','技术学习与探索','#3b6ef5',1],['摸鱼日记','diary','日常所见所闻','#059669',2],['项目作品','projects','项目和作品展示','#d97706',3],['读书笔记','reading','阅读思考笔记','#8b5cf6',4],['生活杂谈','life','生活零零碎碎','#ec4899',5]];
        $st = $pdo->prepare("INSERT IGNORE INTO categories (name,slug,description,color,sort_order) VALUES (?,?,?,?,?)");
        foreach ($cats as $c) $st->execute($c);

        $defs = ['blog_name'=>'摸鱼博客','blog_tagline'=>'在忙碌的间隙，记录生活的温度','blog_desc'=>'一个用液态玻璃风格打造的个人博客','author_name'=>'摸鱼人','author_bio'=>'白天搬砖，夜里写码。喜欢折腾技术，也喜欢在午后的阳光下发呆。','author_role'=>'开发者 · 创作者 · 专业摸鱼人','social_github'=>'','social_twitter'=>'','social_email'=>'hello@moyublog.local','icp_filing'=>'','wish_enabled'=>'1'];
        $st = $pdo->prepare("INSERT IGNORE INTO settings (setting_key,setting_value) VALUES (?,?)");
        foreach ($defs as $k => $v) $st->execute([$k, $v]);

        $pdo->prepare("INSERT IGNORE INTO posts (title,slug,content,excerpt,category_id,type,status,is_featured,published_at) VALUES (?,?,?,?,2,'post','published',1,NOW())")
            ->execute(['欢迎来到摸鱼博客','welcome','<h2>👋 你好呀！</h2><p>这是一个用 <strong>Frostglass 液态玻璃风格</strong> 打造的个人博客。</p><ul><li>📝 记录技术笔记</li><li>🎣 分享摸鱼日常</li><li>🛠️ 展示个人作品</li></ul><p><em>认真工作是为了更好地摸鱼 🐟</em></p>','一个用液态玻璃风格打造的个人博客，记录技术、生活和摸鱼的日常。']);

        $ok = '✨ 安装完成！'; $installed = true;
    } catch (PDOException $e) { $err = '安装失败：' . $e->getMessage(); }
}
